const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  ImageRun, AlignmentType, BorderStyle, WidthType, ShadingType,
  VerticalAlign, TabStopType, TabStopPosition, LevelFormat
} = require('docx');

const LOGO_B64 = "";

const DEEP_BLUE = "0056A8";
const DARK_GRAY = "333333";
const MID_GRAY = "888888";
const LIGHT_GRAY = "F5F7FA";
const WHITE = "FFFFFF";
const CONTENT_WIDTH = 9360;

const fmt = (n) => "$" + Number(n || 0).toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 });

const noBorder = { style: BorderStyle.NONE, size: 0, color: "FFFFFF" };
const noBorders = { top: noBorder, bottom: noBorder, left: noBorder, right: noBorder };
const thinBorder = { style: BorderStyle.SINGLE, size: 1, color: "DDDDDD" };
const thinBorders = { top: thinBorder, bottom: thinBorder, left: thinBorder, right: thinBorder };
const boldBlueBorderBottom = { top: noBorder, left: noBorder, right: noBorder, bottom: { style: BorderStyle.SINGLE, size: 12, color: DEEP_BLUE } };

function p(text, opts = {}) {
  return new Paragraph({
    spacing: { before: opts.before || 0, after: opts.after || 80 },
    alignment: opts.align || AlignmentType.LEFT,
    children: [new TextRun({
      text: text || "",
      font: opts.font || "Open Sans",
      size: opts.size || 20,
      bold: opts.bold || false,
      color: opts.color || DARK_GRAY,
      italics: opts.italics || false,
    })]
  });
}

function spacer(before = 120) {
  return new Paragraph({ spacing: { before, after: 0 }, children: [new TextRun("")] });
}

function labelCell(text, width) {
  return new TableCell({
    width: { size: width, type: WidthType.DXA },
    borders: noBorders,
    shading: { fill: LIGHT_GRAY, type: ShadingType.CLEAR },
    margins: { top: 80, bottom: 80, left: 140, right: 80 },
    children: [new Paragraph({ children: [new TextRun({ text, font: "Open Sans", size: 18, bold: true, color: MID_GRAY })] })]
  });
}

function valueCell(text, width) {
  return new TableCell({
    width: { size: width, type: WidthType.DXA },
    borders: noBorders,
    shading: { fill: LIGHT_GRAY, type: ShadingType.CLEAR },
    margins: { top: 80, bottom: 80, left: 80, right: 140 },
    children: [new Paragraph({ children: [new TextRun({ text: text || "", font: "Open Sans", size: 18, color: DARK_GRAY })] })]
  });
}

exports.handler = async (event) => {
  if (event.httpMethod !== "POST") {
    return { statusCode: 405, body: "Method not allowed" };
  }

  let payload;
  try {
    payload = JSON.parse(event.body);
  } catch {
    return { statusCode: 400, body: JSON.stringify({ error: "Invalid JSON" }) };
  }

  const {
    invoiceNumber, date, dueDate,
    clientName, clientCompany, clientAddress, clientEmail, clientPhone,
    lineItems = [], total,
    paymentMethod, stripeLink, wireDetails, wiseDetails, coordNote
  } = payload;

  try {
    const logoBuffer = Buffer.from(LOGO_B64, "base64");

    // Build payment section content
    const paymentRows = [];
    if (paymentMethod === "stripe" && stripeLink) {
      paymentRows.push(p("Payment Link:", { bold: true, size: 19, color: DARK_GRAY }));
      paymentRows.push(new Paragraph({
        spacing: { before: 40, after: 40 },
        children: [new TextRun({ text: stripeLink, font: "Open Sans", size: 19, color: DEEP_BLUE })]
      }));
      paymentRows.push(p("A processing fee will be applied to the final amount for card payments. This fee is the responsibility of the client.", { size: 18, color: MID_GRAY, italics: true }));
    } else if (paymentMethod === "wire" && wireDetails && wireDetails.bankName) {
      const wRows = [
        ["Bank", wireDetails.bankName],
        ["Account Name", wireDetails.accountName],
        ["Routing (ABA)", wireDetails.routingNumber],
        ["Account Number", wireDetails.accountNumber],
        ["Account Type", wireDetails.accountType],
      ];
      if (wireDetails.swift) wRows.push(["SWIFT / BIC", wireDetails.swift]);
      paymentRows.push(p("Wire Transfer / ACH Instructions:", { bold: true, size: 19 }));
      paymentRows.push(spacer(40));
      paymentRows.push(new Table({
        width: { size: CONTENT_WIDTH, type: WidthType.DXA },
        columnWidths: [2400, 6960],
        rows: wRows.map(([label, value]) => new TableRow({
          children: [labelCell(label, 2400), valueCell(value, 6960)]
        }))
      }));
    } else if (paymentMethod === "wise" && wiseDetails && wiseDetails.email) {
      paymentRows.push(p("Wise Transfer Instructions:", { bold: true, size: 19 }));
      paymentRows.push(spacer(40));
      const wRows = [
        ["Wise Email", wiseDetails.email],
        ["Account Name", wiseDetails.accountName || ""],
        ["Currency", wiseDetails.currency || "USD"],
      ];
      if (wiseDetails.instructions) wRows.push(["Notes", wiseDetails.instructions]);
      paymentRows.push(new Table({
        width: { size: CONTENT_WIDTH, type: WidthType.DXA },
        columnWidths: [2400, 6960],
        rows: wRows.map(([label, value]) => new TableRow({
          children: [labelCell(label, 2400), valueCell(value, 6960)]
        }))
      }));
    }

    if (coordNote) {
      paymentRows.push(spacer(80));
      paymentRows.push(p(coordNote, { size: 18, color: MID_GRAY, italics: true }));
    }

    const doc = new Document({
      styles: { default: { document: { run: { font: "Open Sans", size: 20, color: DARK_GRAY } } } },
      sections: [{
        properties: {
          page: {
            size: { width: 12240, height: 15840 },
            margin: { top: 1080, right: 1080, bottom: 1080, left: 1080 }
          }
        },
        children: [

          // HEADER: Logo left, Invoice title right
          new Table({
            width: { size: CONTENT_WIDTH, type: WidthType.DXA },
            columnWidths: [4680, 4680],
            rows: [new TableRow({
              children: [
                new TableCell({
                  borders: noBorders,
                  width: { size: 4680, type: WidthType.DXA },
                  verticalAlign: VerticalAlign.CENTER,
                  children: [new Paragraph({
                    children: [new ImageRun({
                      type: "png",
                      data: logoBuffer,
                      transformation: { width: 160, height: 102 },
                      altText: { title: "Sourcepoint", description: "Sourcepoint logo", name: "logo" }
                    })]
                  })]
                }),
                new TableCell({
                  borders: noBorders,
                  width: { size: 4680, type: WidthType.DXA },
                  verticalAlign: VerticalAlign.CENTER,
                  children: [
                    new Paragraph({
                      alignment: AlignmentType.RIGHT,
                      children: [new TextRun({ text: "INVOICE", font: "Cinzel", size: 44, bold: true, color: DEEP_BLUE })]
                    }),
                    new Paragraph({
                      alignment: AlignmentType.RIGHT,
                      spacing: { before: 40 },
                      children: [new TextRun({ text: invoiceNumber || "", font: "Open Sans", size: 22, color: DARK_GRAY, bold: true })]
                    }),
                  ]
                }),
              ]
            })]
          }),

          // Blue divider
          new Paragraph({
            spacing: { before: 160, after: 0 },
            border: { bottom: { style: BorderStyle.SINGLE, size: 12, color: DEEP_BLUE, space: 1 } },
            children: [new TextRun("")]
          }),

          spacer(200),

          // FROM + BILL TO side by side
          new Table({
            width: { size: CONTENT_WIDTH, type: WidthType.DXA },
            columnWidths: [4320, 720, 4320],
            rows: [new TableRow({
              children: [
                // FROM
                new TableCell({
                  borders: noBorders,
                  width: { size: 4320, type: WidthType.DXA },
                  children: [
                    new Paragraph({ spacing: { before: 0, after: 60 }, children: [new TextRun({ text: "FROM", font: "Open Sans", size: 17, bold: true, color: MID_GRAY, characterSpacing: 80 })] }),
                    new Paragraph({ spacing: { before: 0, after: 40 }, children: [new TextRun({ text: "Taylor Carson", font: "Open Sans", size: 22, bold: true, color: DARK_GRAY })] }),
                    new Paragraph({ spacing: { before: 0, after: 40 }, children: [new TextRun({ text: "Sourcepoint", font: "Open Sans", size: 20, color: DARK_GRAY })] }),
                    new Paragraph({ spacing: { before: 0, after: 40 }, children: [new TextRun({ text: "hello@sourcepointco.com", font: "Open Sans", size: 19, color: DEEP_BLUE })] }),
                    new Paragraph({ spacing: { before: 0, after: 0 }, children: [new TextRun({ text: "sourcepointco.com", font: "Open Sans", size: 19, color: DEEP_BLUE })] }),
                  ]
                }),
                // Spacer column
                new TableCell({ borders: noBorders, width: { size: 720, type: WidthType.DXA }, children: [new Paragraph({ children: [new TextRun("")] })] }),
                // BILL TO
                new TableCell({
                  borders: noBorders,
                  width: { size: 4320, type: WidthType.DXA },
                  children: [
                    new Paragraph({ spacing: { before: 0, after: 60 }, children: [new TextRun({ text: "BILL TO", font: "Open Sans", size: 17, bold: true, color: MID_GRAY, characterSpacing: 80 })] }),
                    new Paragraph({ spacing: { before: 0, after: 40 }, children: [new TextRun({ text: clientName || "", font: "Open Sans", size: 22, bold: true, color: DARK_GRAY })] }),
                    clientCompany ? new Paragraph({ spacing: { before: 0, after: 40 }, children: [new TextRun({ text: clientCompany, font: "Open Sans", size: 20, color: DARK_GRAY })] }) : null,
                    clientAddress ? new Paragraph({ spacing: { before: 0, after: 40 }, children: [new TextRun({ text: clientAddress, font: "Open Sans", size: 19, color: DARK_GRAY })] }) : null,
                    clientEmail ? new Paragraph({ spacing: { before: 0, after: 40 }, children: [new TextRun({ text: clientEmail, font: "Open Sans", size: 19, color: DARK_GRAY })] }) : null,
                    clientPhone ? new Paragraph({ spacing: { before: 0, after: 0 }, children: [new TextRun({ text: clientPhone, font: "Open Sans", size: 19, color: DARK_GRAY })] }) : null,
                  ].filter(Boolean)
                }),
              ]
            })]
          }),

          spacer(200),

          // Invoice meta: date and due date
          new Table({
            width: { size: CONTENT_WIDTH, type: WidthType.DXA },
            columnWidths: [2340, 2340, 2340, 2340],
            rows: [
              new TableRow({
                children: [
                  new TableCell({ borders: noBorders, width: { size: 2340, type: WidthType.DXA }, shading: { fill: DEEP_BLUE, type: ShadingType.CLEAR }, margins: { top: 100, bottom: 100, left: 140, right: 80 }, children: [new Paragraph({ children: [new TextRun({ text: "Invoice Number", font: "Open Sans", size: 17, bold: true, color: WHITE })] })] }),
                  new TableCell({ borders: noBorders, width: { size: 2340, type: WidthType.DXA }, shading: { fill: DEEP_BLUE, type: ShadingType.CLEAR }, margins: { top: 100, bottom: 100, left: 80, right: 80 }, children: [new Paragraph({ children: [new TextRun({ text: "Date Issued", font: "Open Sans", size: 17, bold: true, color: WHITE })] })] }),
                  new TableCell({ borders: noBorders, width: { size: 2340, type: WidthType.DXA }, shading: { fill: DEEP_BLUE, type: ShadingType.CLEAR }, margins: { top: 100, bottom: 100, left: 80, right: 80 }, children: [new Paragraph({ children: [new TextRun({ text: "Payment Due", font: "Open Sans", size: 17, bold: true, color: WHITE })] })] }),
                  new TableCell({ borders: noBorders, width: { size: 2340, type: WidthType.DXA }, shading: { fill: DEEP_BLUE, type: ShadingType.CLEAR }, margins: { top: 100, bottom: 100, left: 80, right: 140 }, children: [new Paragraph({ children: [new TextRun({ text: "Payment Method", font: "Open Sans", size: 17, bold: true, color: WHITE })] })] }),
                ]
              }),
              new TableRow({
                children: [
                  new TableCell({ borders: noBorders, width: { size: 2340, type: WidthType.DXA }, shading: { fill: LIGHT_GRAY, type: ShadingType.CLEAR }, margins: { top: 100, bottom: 100, left: 140, right: 80 }, children: [new Paragraph({ children: [new TextRun({ text: invoiceNumber || "", font: "Open Sans", size: 19, bold: true, color: DARK_GRAY })] })] }),
                  new TableCell({ borders: noBorders, width: { size: 2340, type: WidthType.DXA }, shading: { fill: LIGHT_GRAY, type: ShadingType.CLEAR }, margins: { top: 100, bottom: 100, left: 80, right: 80 }, children: [new Paragraph({ children: [new TextRun({ text: date || "", font: "Open Sans", size: 19, color: DARK_GRAY })] })] }),
                  new TableCell({ borders: noBorders, width: { size: 2340, type: WidthType.DXA }, shading: { fill: LIGHT_GRAY, type: ShadingType.CLEAR }, margins: { top: 100, bottom: 100, left: 80, right: 80 }, children: [new Paragraph({ children: [new TextRun({ text: dueDate || "Upon receipt", font: "Open Sans", size: 19, color: DARK_GRAY })] })] }),
                  new TableCell({ borders: noBorders, width: { size: 2340, type: WidthType.DXA }, shading: { fill: LIGHT_GRAY, type: ShadingType.CLEAR }, margins: { top: 100, bottom: 100, left: 80, right: 140 }, children: [new Paragraph({ children: [new TextRun({ text: paymentMethod === "stripe" ? "Card (Stripe)" : paymentMethod === "wise" ? "Wise" : "Wire / ACH", font: "Open Sans", size: 19, color: DARK_GRAY })] })] }),
                ]
              }),
            ]
          }),

          spacer(240),

          // Line items table header
          new Table({
            width: { size: CONTENT_WIDTH, type: WidthType.DXA },
            columnWidths: [7200, 2160],
            rows: [
              // Header row
              new TableRow({
                children: [
                  new TableCell({ borders: noBorders, width: { size: 7200, type: WidthType.DXA }, shading: { fill: "0A1628", type: ShadingType.CLEAR }, margins: { top: 100, bottom: 100, left: 140, right: 80 }, children: [new Paragraph({ children: [new TextRun({ text: "Description", font: "Open Sans", size: 18, bold: true, color: WHITE })] })] }),
                  new TableCell({ borders: noBorders, width: { size: 2160, type: WidthType.DXA }, shading: { fill: "0A1628", type: ShadingType.CLEAR }, margins: { top: 100, bottom: 100, left: 80, right: 140 }, children: [new Paragraph({ alignment: AlignmentType.RIGHT, children: [new TextRun({ text: "Amount", font: "Open Sans", size: 18, bold: true, color: WHITE })] })] }),
                ]
              }),
              // Line item rows
              ...(lineItems || []).map((item, i) => new TableRow({
                children: [
                  new TableCell({ borders: { top: noBorder, left: noBorder, right: noBorder, bottom: { style: BorderStyle.SINGLE, size: 1, color: "E2E8F0" } }, width: { size: 7200, type: WidthType.DXA }, shading: { fill: i % 2 === 0 ? WHITE : LIGHT_GRAY, type: ShadingType.CLEAR }, margins: { top: 100, bottom: 100, left: 140, right: 80 }, children: [new Paragraph({ children: [new TextRun({ text: item.desc || "", font: "Open Sans", size: 19, color: DARK_GRAY })] })] }),
                  new TableCell({ borders: { top: noBorder, left: noBorder, right: noBorder, bottom: { style: BorderStyle.SINGLE, size: 1, color: "E2E8F0" } }, width: { size: 2160, type: WidthType.DXA }, shading: { fill: i % 2 === 0 ? WHITE : LIGHT_GRAY, type: ShadingType.CLEAR }, margins: { top: 100, bottom: 100, left: 80, right: 140 }, children: [new Paragraph({ alignment: AlignmentType.RIGHT, children: [new TextRun({ text: fmt(item.amt), font: "Open Sans", size: 19, color: DARK_GRAY })] })] }),
                ]
              })),
              // Total row
              new TableRow({
                children: [
                  new TableCell({ borders: noBorders, width: { size: 7200, type: WidthType.DXA }, shading: { fill: DEEP_BLUE, type: ShadingType.CLEAR }, margins: { top: 120, bottom: 120, left: 140, right: 80 }, children: [new Paragraph({ children: [new TextRun({ text: "TOTAL DUE", font: "Cinzel", size: 22, bold: true, color: WHITE })] })] }),
                  new TableCell({ borders: noBorders, width: { size: 2160, type: WidthType.DXA }, shading: { fill: DEEP_BLUE, type: ShadingType.CLEAR }, margins: { top: 120, bottom: 120, left: 80, right: 140 }, children: [new Paragraph({ alignment: AlignmentType.RIGHT, children: [new TextRun({ text: fmt(total), font: "Cinzel", size: 26, bold: true, color: WHITE })] })] }),
                ]
              }),
            ]
          }),

          spacer(280),

          // Payment instructions section
          new Paragraph({
            spacing: { before: 0, after: 80 },
            border: { bottom: { style: BorderStyle.SINGLE, size: 4, color: DEEP_BLUE, space: 4 } },
            children: [new TextRun({ text: "PAYMENT INSTRUCTIONS", font: "Cinzel", size: 20, bold: true, color: DEEP_BLUE })]
          }),

          spacer(120),

          ...paymentRows,

          spacer(280),

          // Footer
          new Paragraph({
            alignment: AlignmentType.CENTER,
            spacing: { before: 0, after: 60 },
            border: { top: { style: BorderStyle.SINGLE, size: 4, color: DEEP_BLUE, space: 6 } },
            children: [new TextRun({ text: "Thank you for your business.", font: "Open Sans", size: 20, italics: true, color: DARK_GRAY })]
          }),
          new Paragraph({
            alignment: AlignmentType.CENTER,
            spacing: { before: 0, after: 0 },
            children: [new TextRun({ text: "Sourcepoint  |  U.S.-Founded. China-Based. Real Factory Access.", font: "Open Sans", size: 18, color: MID_GRAY })]
          }),
        ]
      }]
    });

    const buffer = await Packer.toBuffer(doc);

    return {
      statusCode: 200,
      headers: {
        "Content-Type": "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
        "Content-Disposition": `attachment; filename="SP_Invoice_${(invoiceNumber || "").replace(/[^a-zA-Z0-9]/g, "_")}.docx"`,
      },
      body: buffer.toString("base64"),
      isBase64Encoded: true,
    };

  } catch (err) {
    console.error("Invoice generation error:", err);
    return {
      statusCode: 500,
      body: JSON.stringify({ message: err.message || "Invoice generation failed" }),
    };
  }
};
